def min_cost(n, m, k):
    # Base case: if k is 0 or k equals total squares, no breaking needed
    if k == 0 or k == n * m:
        return 0

    # Use memoization to avoid recalculations
    memo = {}

    def dp(remaining_n, remaining_m, target):
        if target == 0:
            return 0
        if target == remaining_n * remaining_m:
            return 0
        if (remaining_n, remaining_m, target) in memo:
            return memo[(remaining_n, remaining_m, target)]

        min_cost_val = float('inf')

        # Try all possible horizontal breaks
        for i in range(1, remaining_n):
            # Break into i x remaining_m and (remaining_n - i) x remaining_m
            cost = remaining_m * remaining_m  # cost of breaking: (remaining_m)^2
            # The target could be in the lower part or upper part
            # Consider different ways to distribute target squares
            for t1 in range(max(0, target - (remaining_n - i) * remaining_m), min(target, i * remaining_m) + 1):
                cost_left = dp(i, remaining_m, t1)
                cost_right = dp(remaining_n - i, remaining_m, target - t1)
                total_cost = cost + cost_left + cost_right
                min_cost_val = min(min_cost_val, total_cost)

        # Try all possible vertical breaks
        for j in range(1, remaining_m):
            # Break into remaining_n x j and remaining_n x (remaining_m - j)
            cost = remaining_n * remaining_n  # cost of breaking: (remaining_n)^2
            for t1 in range(max(0, target - remaining_n * (remaining_m - j)), min(target, remaining_n * j) + 1):
                cost_left = dp(remaining_n, j, t1)
                cost_right = dp(remaining_n, remaining_m - j, target - t1)
                total_cost = cost + cost_left + cost_right
                min_cost_val = min(min_cost_val, total_cost)

        memo[(remaining_n, remaining_m, target)] = min_cost_val
        return min_cost_val

    return dp(n, m, k)

