def min_cost(n, m, k):
    # Special case: if we want to eat all squares, no breaking needed
    if k == n * m:
        return 0

    # If we want to eat 0 squares, also no breaking needed
    if k == 0:
        return 0

    # Memoization cache
    memo = {}

    def dp(rows, cols, target):
        if target == 0 or target == rows * cols:
            return 0

        if (rows, cols, target) in memo:
            return memo[(rows, cols, target)]

        min_cost = float('inf')

        # Try all possible horizontal breaks
        for r in range(1, rows):
            # Break into (r, cols) and (rows - r, cols)
            # We can take the target from the top piece, or from the bottom piece
            for take_top in range(max(0, target - (rows - r) * cols), min(target, r * cols) + 1):
                cost = r * cols * cols  # cost of breaking at height r, length = cols
                cost += dp(r, cols, take_top) + dp(rows - r, cols, target - take_top)
                min_cost = min(min_cost, cost)

        # Try all possible vertical breaks
        for c in range(1, cols):
            # Break into (rows, c) and (rows, cols - c)
            # We can take the target from the left piece, or from the right piece
            for take_left in range(max(0, target - rows * (cols - c)), min(target, rows * c) + 1):
                cost = rows * rows * c  # cost of breaking at width c, length = rows
                cost += dp(rows, c, take_left) + dp(rows, cols - c, target - take_left)
                min_cost = min(min_cost, cost)

        memo[(rows, cols, target)] = min_cost
        return min_cost

    return dp(n, m, k)

